const body = $input.first().json.body;
const required = ['company_name', 'announcement_type', 'headline_idea', 'key_facts'];
const missing = required.filter(f => !body[f]);
if (missing.length) return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
if (!Array.isArray(body.key_facts) || body.key_facts.length < 2) return [{ json: { valid: false, error: 'key_facts must be an array with at least 2 items' } }];
const announcementTypes = ['product_launch', 'funding', 'partnership', 'acquisition', 'executive_hire', 'award', 'expansion', 'event', 'research', 'other'];
const announcementType = announcementTypes.includes(body.announcement_type) ? body.announcement_type : 'other';
return [{ json: {
  valid: true,
  companyName: body.company_name.trim(),
  companyDescription: (body.company_description || '').slice(0, 400),
  announcementType,
  headlineIdea: body.headline_idea.trim(),
  keyFacts: body.key_facts.slice(0, 10),
  quotes: Array.isArray(body.quotes) ? body.quotes.slice(0, 3) : [],
  targetMedia: body.target_media || 'general business press',
  tone: body.tone || 'professional',
  embargo: body.embargo || '',
  contactName: body.contact_name || '',
  contactEmail: body.contact_email || '',
  contactPhone: body.contact_phone || '',
  boilerplate: (body.boilerplate || '').slice(0, 400),
  replyEmail: body.reply_email || null,
  requestedAt: new Date().toISOString()
} }];

values.content:
Draft a press release.

Company: {{ $json.companyName }}
Company description: {{ $json.companyDescription || 'not provided' }}
Announcement type: {{ $json.announcementType }}
Headline idea (refine this): {{ $json.headlineIdea }}
Tone: {{ $json.tone }}
Target media: {{ $json.targetMedia }}
Embargo: {{ $json.embargo || 'FOR IMMEDIATE RELEASE' }}

Key facts to include:
{{ $json.keyFacts.map((f, i) => `${i+1}. ${f}`).join('\n') }}

Quotes provided:
{{ $json.quotes.map((q, i) => `Quote ${i+1}: "${q.quote}" — ${q.attribution || 'unattributed'}`).join('\n') || 'None provided — create a placeholder quote' }}

Contact info:
{{ $json.contactName || '[Contact Name]' }} | {{ $json.contactEmail || '[email]' }} | {{ $json.contactPhone || '[phone]' }}

Boilerplate: {{ $json.boilerplate || 'Generate a standard boilerplate based on the company description.' }}

Return this JSON:
{
  "headline": "final polished headline",
  "subheadline": "one-line subheadline",
  "release_date_line": "FOR IMMEDIATE RELEASE or embargo text",
  "dateline": "City, Date --",
  "body": "full press release body text from lede through boilerplate and ### — formatted as one string with paragraph breaks using \\n\\n",
  "headline_alternatives": ["2 alternative headline options"],
  "editor_notes": ["2-3 notes for the PR team: what's strong, what to verify, suggested media targets"]
}

parameters.jsCode:
const raw = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
let draft;
try { draft = JSON.parse(raw.replace(/```json|```/g,'').trim()); } catch(e) { return [{ json: { error: 'Parse error', raw } }]; }
const input = $('Validate Input').first().json;
draft._meta = { companyName: input.companyName, announcementType: input.announcementType, replyEmail: input.replyEmail };
return [{ json: draft }];

const d = $input.first().json;
const m = d._meta;
function esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
const bodyHtml = esc(d.body||'').replace(/\n\n/g,'</p><p style="margin:0 0 14px;font-size:15px;line-height:1.75">').replace(/\n/g,'<br>');
const altHeads = (d.headline_alternatives||[]).map((h,i)=>`<div style="font-size:14px;padding:7px 0;border-bottom:1px solid #f3f4f6;color:#374151">${i+1}. ${esc(h)}</div>`).join('');
const editorNotes = (d.editor_notes||[]).map(n=>`<li style="font-size:13px;margin-bottom:6px;line-height:1.55;color:#374151">${esc(n)}</li>`).join('');
const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="margin:0;padding:16px;background:#f9fafb;font-family:Georgia,'Times New Roman',serif;color:#1a1a1a">
<div style="max-width:700px;margin:0 auto">
  <div style="background:#1a1a1a;color:#fff;padding:20px 28px;border-radius:10px 10px 0 0">
    <div style="font-size:11px;text-transform:uppercase;letter-spacing:1px;color:#6b7280;margin-bottom:5px">Press Release · ${esc(m.announcementType.replace(/_/g,' '))}</div>
    <div style="font-size:20px;font-weight:700;line-height:1.3">${esc(d.headline)}</div>
    <div style="font-size:14px;color:#9ca3af;margin-top:6px;font-style:italic">${esc(d.subheadline)}</div>
  </div>
  <div style="background:#fff;padding:24px 28px;border:1px solid #e5e7eb;border-top:none;font-family:Georgia,serif">
    <div style="font-size:12px;font-weight:700;color:#6b7280;margin-bottom:4px">${esc(d.release_date_line)}</div>
    <div style="font-size:12px;color:#6b7280;margin-bottom:20px">${esc(d.dateline)}</div>
    <p style="margin:0 0 14px;font-size:15px;line-height:1.75">${bodyHtml}</p>
  </div>
  ${altHeads ? `<div style="background:#fff;padding:16px 28px;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:8px">Alternative headlines</div>
    ${altHeads}
  </div>` : ''}
  ${editorNotes ? `<div style="background:#eff6ff;padding:16px 28px;border:1px solid #bfdbfe">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#1d4ed8;margin-bottom:8px">PR team notes</div>
    <ul style="padding-left:18px;margin:0">${editorNotes}</ul>
  </div>` : ''}
  <div style="background:#1a1a1a;color:#4b5563;font-size:11px;padding:12px 28px;border-radius:0 0 10px 10px;font-family:monospace;text-align:center">
    Press Release Drafter · ${new Date().toLocaleDateString()}
  </div>
</div></body></html>`;
return [{ json: { html, replyEmail: m.replyEmail, companyName: m.companyName, headline: d.headline, draft: d } }];
